import { motion } from "framer-motion";

const testimonials = [
  {
    name: "Arun Kumar",
    text:
      "BodyZeal completely changed my fitness journey. Structured workouts & amazing trainers.",
  },
  {
    name: "Priya Sharma",
    text:
      "Clean gym, disciplined environment, and real results. Highly recommended!",
  },
  {
    name: "Vijay Raj",
    text:
      "The best gym experience I've ever had. Worth every rupee.",
  },
];

export default function Testimonials() {
  return (
    <section className="bg-black pt-28 pb-24 px-6 min-h-screen">
      <div className="max-w-6xl mx-auto">
        <h2 className="text-4xl md:text-5xl font-bold text-center text-white mb-16">
          Member <span className="text-[#e9b21a]">Testimonials</span>
        </h2>

        <div className="grid md:grid-cols-3 gap-10">
          {testimonials.map((t, i) => (
            <motion.div
              key={i}
              whileHover={{ scale: 1.05 }}
              className="bg-black/60 border border-white/10 rounded-2xl p-8 shadow-lg"
            >
              <p className="text-gray-300 italic">“{t.text}”</p>
              <h4 className="mt-6 font-semibold text-[#e9b21a]">
                — {t.name}
              </h4>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
